import { useEffect, useMemo, useRef, useState } from "react";
import type { AppHandle } from "@app/kit/primitives";
import { motion, AnimatePresence, LayoutGroup, animate, useReducedMotion } from "motion/react";
import { HeartPulse, Search, Calendar, FileText, Bell, Star, Clock, X, LogOut, Lightbulb, Sparkles, Award, ChevronDown } from "lucide-react";

type Row = Record<string, unknown>;
const FONT = "'Nunito', ui-rounded, 'SF Pro Rounded', system-ui, sans-serif";
const DAY = 86400000;
const WD = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const MO = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const SPEC_TONE: Record<string, string> = {
  "General Practice": "bg-[#E3F6F3] text-[#0B7A6D]",
  Cardiology: "bg-[#FDE8E6] text-[#B73E34]",
  Dermatology: "bg-[#FFF0DD] text-[#A8630F]",
  Pediatrics: "bg-[#E6F0FF] text-[#2E5FB8]",
  Neurology: "bg-[#EEE8FD] text-[#6140B5]",
  Orthopedics: "bg-[#E8F5DD] text-[#477A1E]",
  "Mental Health": "bg-[#FCE8F3] text-[#A8397C]",
};

const s = (v: unknown): string => (v === null || v === undefined ? "" : String(v));
const pad = (n: number) => String(n).padStart(2, "0");
const ms = (v: unknown) => {
  const t = Date.parse(s(v));
  return Number.isNaN(t) ? 0 : t;
};
const hm = (t: number) => {
  const d = new Date(t);
  return pad(d.getUTCHours()) + ":" + pad(d.getUTCMinutes());
};
const dayStart = (t: number) => t - (((t % DAY) + DAY) % DAY);
const dateLong = (t: number) => {
  const d = new Date(t);
  return WD[d.getUTCDay()] + " " + d.getUTCDate() + " " + MO[d.getUTCMonth()];
};
const rel = (t: number, now: number) => {
  const d = Math.round((dayStart(t) - dayStart(now)) / DAY);
  if (d === 0) return "Today";
  if (d === 1) return "Tomorrow";
  return dateLong(t);
};
const until = (t: number, now: number) => {
  const m = Math.round((t - now) / 60000);
  if (m <= 0) return "now";
  if (m < 60) return "in " + m + " min";
  if (m < 1440) return "in " + Math.floor(m / 60) + "h " + (m % 60) + "m";
  return "in " + Math.floor(m / 1440) + " days";
};
const initials = (n: string) => n.replace("Dr. ", "").split(" ").map((p) => p[0] || "").join("").slice(0, 2);

function Photo({ src, name, className }: { src: string; name: string; className: string }) {
  const [bad, setBad] = useState(false);
  if (!src || bad || /\.svg(\?|$)/i.test(src)) {
    return <div className={className + " flex items-center justify-center bg-gradient-to-br from-[#BFEDE6] to-[#7FD6C9] font-extrabold text-[#0B6F63] " + (className.includes("h-full") ? "text-4xl" : "text-xs")}>{initials(name)}</div>;
  }
  return <img src={src} alt={name} loading="lazy" onError={() => setBad(true)} className={className + " object-cover"} />;
}

function Counter({ value }: { value: number }) {
  const reduce = useReducedMotion();
  const [n, setN] = useState(0);
  useEffect(() => {
    if (reduce) {
      setN(value);
      return;
    }
    const c = animate(0, value, { duration: 0.9, ease: "easeOut", onUpdate: (v) => setN(Math.round(v)) });
    return () => c.stop();
  }, [value, reduce]);
  return <>{n}</>;
}

type Tab = "find" | "visits" | "history";

export default function PatientApp({ app, tab: initialTab }: { app?: AppHandle; tab?: string }) {
  const reduce = useReducedMotion();
  const appRef = useRef(app);
  appRef.current = app;
  const [now, setNow] = useState(0);
  const [tab, setTab] = useState<Tab>(initialTab === "visits" || initialTab === "history" ? initialTab : "find");
  const [spec, setSpec] = useState("All");
  const [q, setQ] = useState("");
  const [notifOpen, setNotifOpen] = useState(false);
  const [toast, setToast] = useState("");
  const [cancelId, setCancelId] = useState("");
  const [open, setOpen] = useState<string>("");

  useEffect(() => {
    setNow(Date.now());
    const t = setInterval(() => setNow(Date.now()), 30000);
    return () => clearInterval(t);
  }, []);
  useEffect(() => {
    const a = appRef.current;
    if (!a) return;
    const offs = ["slot", "appointment", "visit_note", "reminder"].map((e) => a.live(e));
    return () => offs.forEach((o) => o());
  }, []);
  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(""), 3600);
    return () => clearTimeout(t);
  }, [toast]);

  const doctors = (app?.rows("doctor") || []) as Row[];
  const appts = (app?.rows("appointment") || []) as Row[];
  const slots = (app?.rows("slot") || []) as Row[];
  const notes = (app?.rows("visit_note") || []) as Row[];
  const reminders = (app?.rows("reminder") || []) as Row[];
  const me = ((app?.rows("patient") || []) as Row[])[0];
  const first = s(me?.name || app?.user.name).split(" ")[0] || "there";
  const loading = !!app?.loading("doctor") && doctors.length === 0;

  const busy = useMemo(() => {
    const m: Record<string, { s: number; e: number }[]> = {};
    slots.forEach((r) => {
      if (r.active === false) return;
      const k = s(r.doctor_id);
      (m[k] = m[k] || []).push({ s: ms(r.starts_at), e: ms(r.ends_at) });
    });
    return m;
  }, [slots]);

  const nextFree = (docId: string): number => {
    if (!now) return 0;
    const base = dayStart(now);
    for (let d = 0; d < 21; d++) {
      for (let m = 480; m < 1080; m += 30) {
        const t = base + d * DAY + m * 60000;
        if (t > now && !(busy[docId] || []).some((b) => b.s < t + 1800000 && b.e > t)) return t;
      }
    }
    return 0;
  };

  const specialties = useMemo(() => ["All"].concat(Array.from(new Set(doctors.map((d) => s(d.specialty)))).filter(Boolean)), [doctors]);
  const shown = doctors
    .filter((d) => (spec === "All" || s(d.specialty) === spec) && (!q || (s(d.name) + " " + s(d.specialty)).toLowerCase().includes(q.toLowerCase())))
    .sort((a, b) => Number(b.rating) - Number(a.rating));

  const mine = appts.slice().sort((a, b) => ms(a.starts_at) - ms(b.starts_at));
  const upcoming = mine.filter((a) => ["booked", "checked_in"].includes(s(a.status)) && ms(a.ends_at) > (now || 0));
  const past = mine.filter((a) => s(a.status) === "completed").reverse();
  const docById = (id: string) => doctors.find((d) => s(d.id) === id);
  const noteFor = (id: string) => notes.find((n) => s(n.appointment_id) === id);
  const next = upcoming[0];

  const feed = useMemo(() => {
    const items: { id: string; t: number; title: string; body: string; kind: "rem" | "note" }[] = [];
    reminders.forEach((r) => items.push({ id: "r" + s(r.id), t: ms(r.created_at), title: "Appointment reminder", body: s(r.message), kind: "rem" }));
    notes.forEach((n) => {
      const ap = appts.find((a) => s(a.id) === s(n.appointment_id));
      items.push({ id: "n" + s(n.id), t: ms(n.created_at), title: "Your visit notes are ready", body: ap ? s(ap.doctor_name) + " added notes from " + s(ap.reason).toLowerCase() + "." : "A new visit note is available.", kind: "note" });
    });
    return items.sort((a, b) => b.t - a.t).slice(0, 8);
  }, [reminders, notes, appts]);
  const fresh = now ? feed.filter((f) => now - f.t < 3 * DAY).length : 0;

  const cancel = async () => {
    const a = appRef.current;
    const id = cancelId;
    setCancelId("");
    if (!a || !id) return;
    try {
      await a.update("appointment", id, { status: "cancelled" });
      setToast("Appointment cancelled. The slot is open for others.");
    } catch (e) {
      setToast(e instanceof Error ? e.message : "Could not cancel this appointment.");
    }
  };

  const spring = reduce ? { duration: 0 } : { type: "spring" as const, stiffness: 320, damping: 28 };
  const NAV: { id: Tab; label: string; Icon: typeof Search }[] = [
    { id: "find", label: "Find a doctor", Icon: Search },
    { id: "visits", label: "My visits", Icon: Calendar },
    { id: "history", label: "History", Icon: FileText },
  ];

  const card = "rounded-[28px] border border-[#E2F2EF] bg-white shadow-[0_1px_2px_rgba(14,43,41,0.04),0_14px_34px_-18px_rgba(18,165,148,0.28)]";
  const empty = "rounded-[32px] border border-dashed border-[#BFE3DD] bg-white/60 p-12 text-center";
  const disk = "mx-auto flex h-20 w-20 items-center justify-center rounded-full bg-[#E3F6F3] text-[#12A594]";

  return (
    <div className="min-h-screen w-full bg-[#F4FBFA] text-[#0E2B29]" style={{ fontFamily: FONT }}>
      <aside className="fixed inset-y-0 left-0 z-30 hidden w-64 flex-col border-r border-[#E2F2EF] bg-white/80 p-5 backdrop-blur lg:flex">
        <div className="mb-8 flex items-center gap-3 text-xl font-extrabold">
          <span className="flex h-10 w-10 items-center justify-center rounded-2xl bg-[#12A594] text-white shadow-[0_10px_20px_-8px_rgba(18,165,148,0.7)]">
            <HeartPulse className="h-5 w-5" />
          </span>
          Clinicly
        </div>
        <LayoutGroup id="side">
          <nav className="space-y-1.5">
            {NAV.map((n) => (
              <button key={n.id} onClick={() => setTab(n.id)} className="relative flex w-full items-center gap-3 rounded-2xl px-4 py-3 text-left text-[15px] font-bold text-[#27504B]">
                {tab === n.id && <motion.span layoutId="sidepill" transition={spring} className="absolute inset-0 rounded-2xl bg-[#E3F6F3]" />}
                <n.Icon className={"relative h-5 w-5 " + (tab === n.id ? "text-[#0E8A7C]" : "text-[#7A9A95]")} />
                <span className={"relative " + (tab === n.id ? "text-[#0B6F63]" : "")}>{n.label}</span>
              </button>
            ))}
          </nav>
        </LayoutGroup>
        <div className="mt-auto rounded-3xl bg-[#F4FBFA] p-4">
          <div className="flex items-center gap-3">
            <Photo src={s(me?.photo)} name={first} className="h-11 w-11 rounded-full" />
            <div className="min-w-0">
              <div className="truncate text-sm font-extrabold">{s(me?.name || app?.user.name)}</div>
              <div className="text-xs font-semibold text-[#7A9A95]">Patient</div>
            </div>
          </div>
          <button onClick={() => void app?.auth.signOut()} className="mt-3 flex w-full items-center justify-center gap-2 rounded-xl bg-white py-2 text-sm font-bold text-[#5B7C77] shadow-sm">
            <LogOut className="h-4 w-4" /> Sign out
          </button>
        </div>
      </aside>

      <div className="lg:pl-64">
        <header className="sticky top-0 z-20 border-b border-[#E2F2EF] bg-white/80 backdrop-blur-xl">
          <div className="mx-auto flex max-w-6xl items-center justify-between px-4 py-3 lg:px-10">
            <div className="flex items-center gap-2.5 text-lg font-extrabold lg:hidden">
              <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#12A594] text-white">
                <HeartPulse className="h-5 w-5" />
              </span>
              Clinicly
            </div>
            <div className="hidden text-[15px] font-extrabold text-[#27504B] lg:block">{NAV.find((n) => n.id === tab)?.label}</div>
            <div className="flex items-center gap-2">
              <motion.button whileTap={{ scale: 0.92 }} aria-label="Notifications" onClick={() => setNotifOpen((v) => !v)} className="relative flex h-10 w-10 items-center justify-center rounded-full bg-[#E3F6F3] text-[#0E8A7C]">
                <Bell className="h-5 w-5" />
                {fresh > 0 && <span className="absolute -right-0.5 -top-0.5 flex h-5 min-w-5 items-center justify-center rounded-full bg-[#FF7A59] px-1 text-[11px] font-extrabold text-white">{fresh}</span>}
              </motion.button>
              <button onClick={() => void app?.auth.signOut()} aria-label="Sign out" className="lg:hidden">
                <Photo src={s(me?.photo)} name={first} className="h-10 w-10 rounded-full" />
              </button>
            </div>
          </div>
        </header>

        <AnimatePresence>
          {notifOpen && (
            <motion.div initial={{ opacity: 0, y: -10, scale: 0.98 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: -10 }} className="fixed left-3 right-3 top-[68px] z-40 rounded-[28px] border border-[#E2F2EF] bg-white p-3 shadow-[0_30px_60px_-20px_rgba(14,43,41,0.3)] sm:left-auto sm:right-6 sm:w-[390px] lg:right-10">
              <div className="flex items-center justify-between px-3 py-2">
                <div className="text-[15px] font-extrabold">Notifications</div>
                <button onClick={() => setNotifOpen(false)} aria-label="Close" className="rounded-full p-1 text-[#7A9A95]"><X className="h-4 w-4" /></button>
              </div>
              {feed.length === 0 && <div className="px-3 pb-4 text-sm font-semibold text-[#7A9A95]">You are all caught up.</div>}
              <div className="max-h-[60vh] space-y-1 overflow-y-auto">
                {feed.map((f, i) => (
                  <motion.div key={f.id} initial={{ opacity: 0, x: 12 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: i * 0.04 }} className="flex gap-3 rounded-2xl p-3 hover:bg-[#F4FBFA]">
                    <span className={"mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-xl " + (f.kind === "rem" ? "bg-[#FFF0DD] text-[#A8630F]" : "bg-[#E3F6F3] text-[#0E8A7C]")}>
                      {f.kind === "rem" ? <Clock className="h-4 w-4" /> : <FileText className="h-4 w-4" />}
                    </span>
                    <div className="min-w-0">
                      <div className="text-sm font-extrabold">{f.title}</div>
                      <div className="text-[13px] font-semibold leading-snug text-[#5B7C77]">{f.body}</div>
                    </div>
                  </motion.div>
                ))}
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        <main className="mx-auto max-w-6xl px-4 pb-32 pt-5 lg:px-10 lg:pb-14 lg:pt-8">
          <AnimatePresence mode="wait">
            <motion.div key={tab} initial={reduce ? false : { opacity: 0, y: 14 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -8 }} transition={{ duration: 0.22 }}>
              {tab === "find" && (
                <div>
                  <div className="relative overflow-hidden rounded-[32px] bg-[linear-gradient(135deg,#0E8A7C_0%,#12A594_55%,#4FCDBB_100%)] p-6 text-white shadow-[0_24px_50px_-24px_rgba(18,165,148,0.8)] lg:p-9">
                    <motion.div className="absolute -right-10 -top-10 h-52 w-52 rounded-full bg-white/15" animate={reduce ? undefined : { scale: [1, 1.08, 1] }} transition={{ duration: 7, repeat: Infinity }} />
                    <motion.div className="absolute -bottom-16 right-24 h-44 w-44 rounded-full bg-white/10" animate={reduce ? undefined : { y: [0, -14, 0] }} transition={{ duration: 8, repeat: Infinity }} />
                    <div className="relative max-w-xl">
                      <div className="text-sm font-bold text-white/80">{now && new Date(now).getUTCHours() < 12 ? "Good morning" : "Hello"}, {first}</div>
                      <h1 className="mt-1 text-[28px] font-extrabold leading-tight lg:text-4xl" style={{ fontFamily: FONT }}>How can we help you today?</h1>
                      <div className="relative mt-5">
                        <Search className="absolute left-4 top-1/2 h-5 w-5 -translate-y-1/2 text-[#7A9A95]" />
                        <input aria-label="Search doctors" value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search by name or specialty" className="w-full rounded-2xl border-0 bg-white py-3.5 pl-12 pr-4 text-[15px] font-semibold text-[#0E2B29] outline-none placeholder:text-[#9BB8B3] focus:ring-4 focus:ring-white/40" />
                      </div>
                      {next && (
                        <button onClick={() => setTab("visits")} className="mt-4 flex w-full items-center gap-3 rounded-2xl bg-white/15 px-4 py-3 text-left backdrop-blur">
                          <Clock className="h-5 w-5 shrink-0" />
                          <span className="min-w-0 truncate text-sm font-bold">Next: {s(next.reason)} · {rel(ms(next.starts_at), now)} {hm(ms(next.starts_at))}</span>
                          <span className="ml-auto shrink-0 rounded-full bg-white px-2.5 py-1 text-xs font-extrabold text-[#0B6F63]">{until(ms(next.starts_at), now)}</span>
                        </button>
                      )}
                    </div>
                  </div>

                  <div className="-mx-4 mt-5 overflow-x-auto px-4 pb-1 lg:mx-0 lg:px-0">
                    <LayoutGroup id="spec">
                      <div className="flex w-max gap-2">
                        {specialties.map((sp) => (
                          <button key={sp} onClick={() => setSpec(sp)} className="relative rounded-full px-4 py-2 text-sm font-extrabold">
                            {spec === sp && <motion.span layoutId="specpill" transition={spring} className="absolute inset-0 rounded-full bg-[#12A594]" />}
                            {spec !== sp && <span className="absolute inset-0 rounded-full border border-[#D6ECE8] bg-white" />}
                            <span className={"relative " + (spec === sp ? "text-white" : "text-[#27504B]")}>{sp}</span>
                          </button>
                        ))}
                      </div>
                    </LayoutGroup>
                  </div>

                  <div className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
                    {loading && [0, 1, 2].map((i) => <div key={i} className={card + " h-40 animate-pulse bg-[#EAF6F4] sm:h-72"} />)}
                    <AnimatePresence mode="popLayout">
                      {shown.map((d, i) => {
                        const nf = nextFree(s(d.id));
                        return (
                          <motion.div key={s(d.id)} layout initial={reduce ? false : { opacity: 0, y: 24 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, scale: 0.96 }} transition={{ ...spring, delay: reduce ? 0 : Math.min(i, 8) * 0.05 }} whileTap={{ scale: 0.98 }} whileHover={reduce ? undefined : { y: -4 }} className={card + " flex cursor-pointer gap-4 overflow-hidden p-3 sm:flex-col sm:gap-0 sm:p-0"} onClick={() => app?.navigate("/book/" + s(d.id))}>
                            <div className="relative h-32 w-28 shrink-0 overflow-hidden rounded-[22px] sm:h-52 sm:w-full sm:rounded-none">
                              <Photo src={s(d.photo)} name={s(d.name)} className="h-full w-full" />
                              <div className="absolute bottom-2 left-2 flex items-center gap-1 rounded-full bg-white/95 px-2.5 py-1 text-xs font-extrabold shadow">
                                <Star className="h-3.5 w-3.5 fill-[#F5B544] text-[#F5B544]" /> {Number(d.rating).toFixed(1)} <span className="font-semibold text-[#7A9A95]">({s(d.review_count)})</span>
                              </div>
                            </div>
                            <div className="flex min-w-0 flex-1 flex-col py-1 sm:p-5">
                              <span className={"mb-2 w-fit rounded-full px-2.5 py-1 text-[11px] font-extrabold " + (SPEC_TONE[s(d.specialty)] || "bg-[#E3F6F3] text-[#0B7A6D]")}>{s(d.specialty)}</span>
                              <div className="truncate text-[17px] font-extrabold" style={{ fontFamily: FONT }}>{s(d.name)}</div>
                              <div className="mt-0.5 flex items-center gap-1 text-[13px] font-semibold text-[#7A9A95]"><Award className="h-3.5 w-3.5" /> {s(d.years_experience)} yrs · {s(d.room)}</div>
                              <div className="mt-auto flex items-end justify-between gap-2 pt-3">
                                <div className="text-xs font-bold text-[#5B7C77]">
                                  <div className="text-[#9BB8B3]">Next available</div>
                                  <div className="text-[13px] text-[#0B7A6D]">{nf ? rel(nf, now) + " " + hm(nf) : "—"}</div>
                                </div>
                                <span className="rounded-xl bg-[#12A594] px-4 py-2 text-sm font-extrabold text-white shadow-[0_8px_16px_-8px_rgba(18,165,148,0.8)]">Book</span>
                              </div>
                            </div>
                          </motion.div>
                        );
                      })}
                    </AnimatePresence>
                  </div>
                  {!loading && shown.length === 0 && (
                    <div className="mt-8 rounded-[28px] border border-dashed border-[#BFE3DD] p-10 text-center">
                      <Search className="mx-auto h-8 w-8 text-[#7FD6C9]" />
                      <div className="mt-3 font-extrabold">No doctors match that search</div>
                      <div className="text-sm font-semibold text-[#7A9A95]">Try another specialty or clear the search.</div>
                    </div>
                  )}
                </div>
              )}

              {tab === "visits" && (
                <div>
                  <div className="mb-5 flex items-end justify-between">
                    <div>
                      <h1 className="text-[28px] font-extrabold" style={{ fontFamily: FONT }}>My visits</h1>
                      <p className="text-sm font-semibold text-[#7A9A95]">Everything coming up, with what to prepare.</p>
                    </div>
                    <div className="flex gap-3 text-center">
                      <div className="rounded-2xl bg-white px-4 py-2 shadow-sm"><div className="text-xl font-extrabold text-[#0E8A7C]"><Counter value={upcoming.length} /></div><div className="text-[11px] font-bold text-[#7A9A95]">Upcoming</div></div>
                      <div className="rounded-2xl bg-white px-4 py-2 shadow-sm"><div className="text-xl font-extrabold text-[#0E8A7C]"><Counter value={past.length} /></div><div className="text-[11px] font-bold text-[#7A9A95]">Past</div></div>
                    </div>
                  </div>
                  <div className="grid gap-4 lg:grid-cols-2">
                    <AnimatePresence mode="popLayout">
                      {upcoming.map((a, i) => {
                        const d = docById(s(a.doctor_id));
                        const t = ms(a.starts_at);
                        return (
                          <motion.div key={s(a.id)} layout initial={reduce ? false : { opacity: 0, y: 24 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, scale: 0.94 }} transition={{ ...spring, delay: reduce ? 0 : i * 0.06 }} className={card + " p-5"}>
                            <div className="flex gap-4">
                              <div className="flex h-16 w-16 shrink-0 flex-col items-center justify-center rounded-2xl bg-[#E3F6F3] text-[#0B6F63]">
                                <div className="text-2xl font-extrabold leading-none">{new Date(t).getUTCDate()}</div>
                                <div className="text-[11px] font-extrabold uppercase">{MO[new Date(t).getUTCMonth()]}</div>
                              </div>
                              <div className="min-w-0 flex-1">
                                <div className="flex items-start justify-between gap-2">
                                  <div className="text-[17px] font-extrabold leading-tight">{s(a.reason)}</div>
