                                <div className="mt-1 flex items-center gap-1.5 text-sm font-bold text-[#0B7A6D]"><Clock className="h-4 w-4" /> {rel(t, now)}, {hm(t)}–{hm(ms(a.ends_at))} · {until(t, now)}</div>
                              </div>
