                      <div className="mt-4 text-lg font-extrabold">Nothing booked yet</div>
                      <div className="mt-1 text-sm font-semibold text-[#7A9A95]">Find a doctor and pick a time that suits you.</div>
                      <button onClick={() => setTab("find")} className="mt-5 rounded-2xl bg-[#12A594] px-6 py-3 text-sm font-extrabold text-white">Find a doctor</button>
                    </div>
