                    {past.map((a, i) => {
                      const d = docById(s(a.doctor_id));
                      const n = noteFor(s(a.id));
                      const isOpen = open === s(a.id) || (open === "" && i === 0);
                      return (
                        <motion.div key={s(a.id)} initial={reduce ? false : { opacity: 0, y: 22 }} animate={{ opacity: 1, y: 0 }} transition={{ ...spring, delay: i * 0.06 }} className="relative sm:pl-16">
                          <span className="absolute left-[18px] top-7 hidden h-5 w-5 rounded-full border-4 border-[#F4FBFA] bg-[#12A594] sm:block" />
                          <div className={card + " overflow-hidden"}>
                            <button className="flex w-full items-center gap-4 p-4 text-left" onClick={() => setOpen(isOpen ? "none" : s(a.id))}>
                              <Photo src={s(d?.photo)} name={s(a.doctor_name)} className="h-14 w-14 shrink-0 rounded-2xl" />
                              <div className="min-w-0 flex-1">
                                <div className="truncate text-[16px] font-extrabold">{s(a.reason)}</div>
                                <div className="truncate text-sm font-bold text-[#5B7C77]">{s(a.doctor_name)} · {dateLong(ms(a.starts_at))}</div>
                                {n && <div className="mt-1 text-[13px] font-extrabold text-[#0B7A6D]">{s(n.diagnosis)}</div>}
                              </div>
                              <motion.span animate={{ rotate: isOpen ? 180 : 0 }} className="text-[#7A9A95]"><ChevronDown className="h-5 w-5" /></motion.span>
                            </button>
                            <AnimatePresence initial={false}>
                              {isOpen && (
                                <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden">
                                  <div className="space-y-3 border-t border-[#EAF4F2] p-4 pt-4">
                                    {n ? (
                                      [["What we found", s(n.summary)], ["Diagnosis", s(n.diagnosis)], ["Plan", s(n.plan)], ["Follow-up", s(n.follow_up)]].filter((r) => r[1]).map((r) => (
                                        <div key={r[0]} className="rounded-2xl bg-[#F4FBFA] p-3.5">
                                          <div className="text-[11px] font-extrabold uppercase tracking-wide text-[#0E8A7C]">{r[0]}</div>
                                          <div className="mt-1 text-[14px] font-semibold leading-relaxed text-[#27504B]">{r[1]}</div>
                                        </div>
                                      ))
                                    ) : (
                                      <div className="text-sm font-semibold text-[#7A9A95]">Notes from this visit will appear here.</div>
                                    )}
                                  </div>
                                </motion.div>
                              )}
                            </AnimatePresence>
                          </div>
                        </motion.div>
                      );
                    })}
                    {past.length === 0 && (
                      <div className={empty}>
                        <div className={disk}><FileText className="h-9 w-9" /></div>
                        <div className="mt-4 text-lg font-extrabold">No visits yet</div>
                        <div className="mt-1 text-sm font-semibold text-[#7A9A95]">After your first appointment, your doctor's notes will show up here.</div>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </motion.div>
          </AnimatePresence>
        </main>
      </div>

      <LayoutGroup id="tabs">
        <nav className="fixed inset-x-3 bottom-3 z-30 flex rounded-[26px] border border-white/70 bg-white/85 p-1.5 shadow-[0_20px_50px_-12px_rgba(14,43,41,0.35)] backdrop-blur-xl lg:hidden">
          {NAV.map((n) => (
            <button key={n.id} onClick={() => setTab(n.id)} className="relative flex flex-1 flex-col items-center gap-0.5 rounded-[20px] py-2 text-[11px] font-extrabold">
              {tab === n.id && <motion.span layoutId="tabpill" transition={spring} className="absolute inset-0 rounded-[20px] bg-[#E3F6F3]" />}
              <n.Icon className={"relative h-5 w-5 " + (tab === n.id ? "text-[#0E8A7C]" : "text-[#7A9A95]")} />
              <span className={"relative " + (tab === n.id ? "text-[#0B6F63]" : "text-[#7A9A95]")}>{n.id === "find" ? "Doctors" : n.label}</span>
            </button>
          ))}
        </nav>
      </LayoutGroup>

      <AnimatePresence>
        {cancelId && (
          <motion.div key="cancel" className="fixed inset-0 z-50 flex items-center justify-center bg-[#0E2B29]/40 p-5" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setCancelId("")}>
            <motion.div initial={{ scale: 0.92, y: 20 }} animate={{ scale: 1, y: 0 }} exit={{ scale: 0.95, opacity: 0 }} onClick={(e) => e.stopPropagation()} className="w-full max-w-sm rounded-[28px] bg-white p-6 text-center shadow-2xl">
              <div className="text-lg font-extrabold">Cancel this visit?</div>
              <p className="mt-1 text-sm font-semibold text-[#7A9A95]">The time will be released for other patients.</p>
              <div className="mt-5 grid grid-cols-2 gap-3">
                <button onClick={() => setCancelId("")} className="rounded-2xl bg-[#F0F7F6] py-3 text-sm font-extrabold text-[#27504B]">Keep it</button>
                <button onClick={() => void cancel()} className="rounded-2xl bg-[#E5594F] py-3 text-sm font-extrabold text-white">Cancel visit</button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {toast && (
          <motion.div key="toast" initial={{ opacity: 0, y: 30, scale: 0.95 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: 20 }} className="fixed inset-x-4 bottom-24 z-[60] mx-auto flex max-w-md items-center gap-3 rounded-2xl bg-[#0E2B29] px-4 py-3.5 text-sm font-bold text-white shadow-2xl lg:bottom-8">
            <Sparkles className="h-5 w-5 shrink-0 text-[#5CD0C0]" /> {toast}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import type { AppHandle } from "@app/kit/primitives";
import { motion, AnimatePresence, LayoutGroup, animate, useReducedMotion } from "motion/react";
import { HeartPulse, ChevronLeft, ChevronRight, Clock, FileText, Sparkles, Check, CheckCircle, X, LogOut, Users, UserCheck, Lightbulb, AlertCircle } from "lucide-react";

type Row = Record<string, unknown>;
const FONT = "'Nunito', ui-rounded, 'SF Pro Rounded', system-ui, sans-serif";
const DAY = 86400000;
const H = 84;
const START = 8;
const WD = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const MO = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const ST: Record<string, { label: string; chip: string; card: string }> = {
  booked: { label: "Booked", chip: "bg-[#E6F0FF] text-[#2E5FB8]", card: "border-[#D6ECE8] bg-white" },
  checked_in: { label: "Waiting", chip: "bg-[#FFF0DD] text-[#A8630F]", card: "border-[#F5D9A8] bg-[#FFF9EE]" },
  completed: { label: "Done", chip: "bg-[#E8F5DD] text-[#477A1E]", card: "border-[#DCEBD0] bg-[#F5FAF0] opacity-90" },
  cancelled: { label: "Cancelled", chip: "bg-[#F1F1F1] text-[#888]", card: "border-dashed border-[#DDD] bg-[#FAFAFA] opacity-60" },
};

const s = (v: unknown): string => (v === null || v === undefined ? "" : String(v));
const pad = (n: number) => String(n).padStart(2, "0");
const ms = (v: unknown) => {
  const t = Date.parse(s(v));
  return Number.isNaN(t) ? 0 : t;
};
const hm = (t: number) => {
  const d = new Date(t);
  return pad(d.getUTCHours()) + ":" + pad(d.getUTCMinutes());
};
const dayStart = (t: number) => t - (((t % DAY) + DAY) % DAY);
const dateLong = (t: number) => {
  const d = new Date(t);
  return WD[d.getUTCDay()] + " " + d.getUTCDate() + " " + MO[d.getUTCMonth()];
};
const initials = (n: string) => n.replace("Dr. ", "").split(" ").map((p) => p[0] || "").join("").slice(0, 2);

function Photo({ src, name, className }: { src: string; name: string; className: string }) {
  const [bad, setBad] = useState(false);
  if (!src || bad || /\.svg(\?|$)/i.test(src)) {
    return <div className={className + " flex items-center justify-center bg-gradient-to-br from-[#BFEDE6] to-[#7FD6C9] text-xs font-extrabold text-[#0B6F63]"}>{initials(name)}</div>;
  }
  return <img src={src} alt={name} onError={() => setBad(true)} className={className + " object-cover"} />;
}

function Counter({ value }: { value: number }) {
  const reduce = useReducedMotion();
  const [n, setN] = useState(0);
  useEffect(() => {
    if (reduce) {
      setN(value);
      return;
    }
    const c = animate(0, value, { duration: 0.8, ease: "easeOut", onUpdate: (v) => setN(Math.round(v)) });
    return () => c.stop();
  }, [value, reduce]);
  return <>{n}</>;
}

const field = "w-full rounded-2xl border border-[#D6ECE8] bg-white px-4 py-3 text-[14px] font-semibold text-[#0E2B29] outline-none placeholder:text-[#9BB8B3] focus:border-[#12A594] focus:ring-4 focus:ring-[#12A594]/15";

function Detail({ a, appts, notes, app, onDone, onClose }: { a: Row; appts: Row[]; notes: Row[]; app?: AppHandle; onDone: (m: string) => void; onClose?: () => void }) {
  const reduce = useReducedMotion();
  const id = s(a.id);
  const [form, setForm] = useState({ summary: "", diagnosis: "", plan: "", follow_up: "" });
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [ai, setAi] = useState("");
  const [aiBusy, setAiBusy] = useState(false);
  const [vs, setVs] = useState("");
  const [vsBusy, setVsBusy] = useState(false);
  const [vsFail, setVsFail] = useState(false);
  useEffect(() => {
    setForm({ summary: "", diagnosis: "", plan: "", follow_up: "" });
    setErr("");
    setAi("");
    setVs("");
    setVsFail(false);
  }, [id]);

  const status = s(a.status);
  const own = notes.find((n) => s(n.appointment_id) === id);
  const history = appts
    .filter((x) => s(x.patient_id) === s(a.patient_id) && s(x.id) !== id && s(x.status) === "completed")
    .sort((x, y) => ms(y.starts_at) - ms(x.starts_at));
  const noteOf = (x: Row) => notes.find((n) => s(n.appointment_id) === s(x.id));
  const open = status === "booked" || status === "checked_in";

  const complete = async () => {
    if (!app || busy) return;
    if (!form.summary.trim() || !form.diagnosis.trim()) {
      setErr("Add a summary and a diagnosis before completing the visit.");
      return;
    }
    setBusy(true);
    setErr("");
    try {
      await app.create("visit_note", { appointment_id: id, patient_id: s(a.patient_id), doctor_id: app.me("doctor"), summary: form.summary.trim(), diagnosis: form.diagnosis.trim(), plan: form.plan.trim() || "No further plan.", follow_up: form.follow_up.trim() || null });
      await app.transition("appointment", id, "status", "completed");
      onDone(s(a.patient_name) + " has been notified that their notes are ready.");
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Could not save the notes.");
    } finally {
      setBusy(false);
    }
  };

  const summarise = async () => {
    if (!app || aiBusy) return;
    setAiBusy(true);
    setAi("");
    const lines = history.map((x) => {
      const n = noteOf(x);
      return dateLong(ms(x.starts_at)) + " " + s(x.reason) + (n ? ": " + s(n.summary) + " Dx: " + s(n.diagnosis) + ". Plan: " + s(n.plan) : "");
    });
    try {
      const r = await app.ai.ask("Patient: " + s(a.patient_name) + " (" + s(a.patient_info) + "). Today's reason: " + s(a.reason) + ".\nPrevious visits:\n" + (lines.join("\n") || "None on record."), { system: "You summarise a patient's history for their doctor in at most 4 short bullet points, then one line starting 'Watch:' for anything to follow up. Use only the facts given; never invent details.", maxTokens: 320 });
      setAi(r);
    } catch {
      setAi("The summary is unavailable right now. Previous visits are listed below.");
    } finally {
      setAiBusy(false);
    }
  };

  const noteSrc = own ? { summary: s(own.summary), diagnosis: s(own.diagnosis), plan: s(own.plan), follow_up: s(own.follow_up) } : form;
  const hasNotes = !!(noteSrc.summary.trim() || noteSrc.plan.trim());
  const visitSummary = async () => {
    if (!app || vsBusy || !hasNotes) return;
    setVsBusy(true);
    setVsFail(false);
    setVs("");
    try {
      const r = await app.ai.ask("Visit notes for " + s(a.patient_name) + " (reason: " + s(a.reason) + ")\nSummary: " + noteSrc.summary + "\nDiagnosis: " + noteSrc.diagnosis + "\nPlan: " + noteSrc.plan + "\nFollow-up: " + noteSrc.follow_up, { system: "You write a short, warm, plain-language visit summary for a patient from their doctor's visit notes: 2-3 sentences, then 'Next steps:' with up to 4 short bullet points. Use ONLY facts in the notes. Never diagnose, never add medical advice, doses, causes or reassurance beyond what the notes say; if something is missing, leave it out. No headings besides 'Next steps:'.", maxTokens: 300 });
      setVs(r);
    } catch {
      setVsFail(true);
    } finally {
      setVsBusy(false);
    }
  };

  return (
    <div style={{ fontFamily: FONT }}>
      <div className="flex items-start gap-4">
        <Photo src={s(a.patient_photo)} name={s(a.patient_name)} className="h-16 w-16 shrink-0 rounded-[22px]" />
        <div className="min-w-0 flex-1">
          <div className="truncate text-xl font-extrabold">{s(a.patient_name)}</div>
          <div className="text-[13px] font-bold text-[#5B7C77]">{s(a.patient_info)}</div>
          <span className={"mt-1.5 inline-block rounded-full px-2.5 py-1 text-[11px] font-extrabold " + (ST[status] || ST.booked).chip}>{(ST[status] || ST.booked).label}</span>
        </div>
        {onClose && <button onClick={onClose} aria-label="Close" className="flex h-9 w-9 items-center justify-center rounded-full bg-[#F0F7F6] text-[#27504B]"><X className="h-4 w-4" /></button>}
      </div>

      <div className="mt-4 grid grid-cols-2 gap-3">
        <div className="rounded-2xl bg-[#F4FBFA] p-3"><div className="text-[11px] font-extrabold uppercase text-[#7A9A95]">When</div><div className="text-sm font-extrabold">{dateLong(ms(a.starts_at))}</div><div className="text-sm font-bold text-[#0B7A6D]">{hm(ms(a.starts_at))}–{hm(ms(a.ends_at))}</div></div>
        <div className="rounded-2xl bg-[#F4FBFA] p-3"><div className="text-[11px] font-extrabold uppercase text-[#7A9A95]">Reason</div><div className="text-sm font-extrabold leading-snug">{s(a.reason)}</div></div>
      </div>
      {s(a.prep_notes) && (
        <div className="mt-3 flex gap-2.5 rounded-2xl bg-[#FFF7E8] p-3"><Lightbulb className="mt-0.5 h-4 w-4 shrink-0 text-[#C98410]" /><div className="text-[13px] font-semibold text-[#7A5A12]">{s(a.prep_notes)}</div></div>
      )}

      <div className="mt-5">
        <div className="mb-2 flex items-center justify-between">
          <div className="text-[15px] font-extrabold">Patient history</div>
          <motion.button whileTap={{ scale: 0.95 }} onClick={() => void summarise()} disabled={aiBusy} className="flex items-center gap-1.5 rounded-full bg-[#12A594] px-3.5 py-1.5 text-xs font-extrabold text-white shadow-[0_8px_16px_-8px_rgba(18,165,148,0.9)] disabled:opacity-70">
                <Sparkles className="h-3.5 w-3.5" /> {aiBusy ? "Summarising…" : "Summarise with AI"}
          </motion.button>
        </div>
        <AnimatePresence>
          {(aiBusy || ai) && (
            <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: "auto" }} exit={{ opacity: 0, height: 0 }} className="mb-3 overflow-hidden rounded-2xl bg-gradient-to-br from-[#E3F6F3] to-[#F4FBFA] ring-1 ring-[#BFE3DD]">
              <div className="p-3.5">
                {aiBusy ? (
                  <div className="space-y-2">{[90, 75, 60].map((w) => <div key={w} className="h-3 animate-pulse rounded-full bg-[#BFE3DD]" style={{ width: w + "%" }} />)}</div>
                ) : (
                  <div className="whitespace-pre-line text-[13px] font-semibold leading-relaxed text-[#27504B]">{ai}</div>
                )}
              </div>
            </motion.div>
          )}
        </AnimatePresence>
        <div className="space-y-2">
          {history.map((x, i) => {
            const n = noteOf(x);
            return (
              <motion.div key={s(x.id)} initial={reduce ? false : { opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }} className="rounded-2xl border border-[#E2F2EF] bg-white p-3">
                <div className="flex items-center justify-between text-xs font-extrabold text-[#7A9A95]"><span>{dateLong(ms(x.starts_at))}</span><span>{s(x.reason)}</span></div>
                {n ? (<><div className="mt-1 text-sm font-extrabold text-[#0B7A6D]">{s(n.diagnosis)}</div><div className="text-[13px] font-semibold leading-snug text-[#5B7C77]">{s(n.summary)}</div></>) : <div className="mt-1 text-[13px] font-semibold text-[#9BB8B3]">No notes recorded.</div>}
              </motion.div>
            );
          })}
          {history.length === 0 && <div className="rounded-2xl border border-dashed border-[#BFE3DD] p-4 text-center text-sm font-semibold text-[#7A9A95]">First visit with you. No earlier notes.</div>}
        </div>
      </div>

      {open && (
        <div className="mt-5 rounded-[24px] bg-[#F4FBFA] p-4">
          <div className="mb-3 flex items-center gap-2 text-[15px] font-extrabold"><FileText className="h-4 w-4 text-[#12A594]" /> Visit notes</div>
          <div className="space-y-2.5">
            <textarea aria-label="Summary" rows={3} className={field} placeholder="What happened in the visit?" value={form.summary} onChange={(e) => setForm({ ...form, summary: e.target.value })} />
            <input aria-label="Diagnosis" className={field} placeholder="Diagnosis" value={form.diagnosis} onChange={(e) => setForm({ ...form, diagnosis: e.target.value })} />
            <textarea aria-label="Plan" rows={2} className={field} placeholder="Plan and prescriptions" value={form.plan} onChange={(e) => setForm({ ...form, plan: e.target.value })} />
            <input aria-label="Follow-up" className={field} placeholder="Follow-up (e.g. 4 weeks)" value={form.follow_up} onChange={(e) => setForm({ ...form, follow_up: e.target.value })} />
          </div>
          <AnimatePresence>{err && <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="mt-3 flex gap-2 rounded-xl bg-[#FDECEC] px-3 py-2 text-[13px] font-bold text-[#B42318]"><AlertCircle className="h-4 w-4 shrink-0" /> {err}</motion.div>}</AnimatePresence>
          <motion.button whileTap={{ scale: 0.97 }} onClick={() => void complete()} disabled={busy} className="mt-3 flex w-full items-center justify-center gap-2 rounded-2xl bg-[#12A594] py-3.5 text-[15px] font-extrabold text-white shadow-[0_12px_24px_-10px_rgba(18,165,148,0.8)] disabled:opacity-70">
            <Check className="h-5 w-5" /> {busy ? "Saving…" : "Save notes & mark completed"}
          </motion.button>
        </div>
      )}
      {status === "completed" && own && (
        <div className="mt-5 rounded-[24px] bg-[#F5FAF0] p-4">
          <div className="mb-2 flex items-center gap-2 text-[15px] font-extrabold text-[#477A1E]"><CheckCircle className="h-4 w-4" /> Notes for this visit</div>
          {[["Summary", s(own.summary)], ["Diagnosis", s(own.diagnosis)], ["Plan", s(own.plan)], ["Follow-up", s(own.follow_up)]].filter((r) => r[1]).map((r) => (
            <div key={r[0]} className="mb-2 last:mb-0"><div className="text-[11px] font-extrabold uppercase text-[#7A9A95]">{r[0]}</div><div className="text-[13px] font-semibold text-[#27504B]">{r[1]}</div></div>
          ))}
        </div>
      )}
      {status !== "cancelled" && (
