export default function ClinicLogin({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const auth = app?.auth;
  const [localMode, setLocalMode] = useState<"in" | "up">("in");
  const rawMode = auth ? (auth as { mode?: string }).mode : undefined;
  const mode: "in" | "up" = rawMode === "up" || rawMode === "signUp" || rawMode === "signup" ? "up" : rawMode ? "in" : localMode;
  const canSignUp = auth ? (auth as { canSignUp?: boolean }).canSignUp !== false : true;
  const providers = ((auth as { providers?: { name: string; label: string }[] } | undefined)?.providers || []) as { name: string; label: string }[];
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  const flip = () => {
    setErr("");
    const next = mode === "in" ? "up" : "in";
    setLocalMode(next);
    const sm = (auth as { setMode?: (m: string) => void } | undefined)?.setMode;
    if (sm) sm(next);
  };

  const submit = async () => {
    if (!auth || busy) return;
    setBusy(true);
    setErr("");
    try {
      if (mode === "in") await auth.signIn(email, password);
      else await auth.signUp({ name: name || email.split("@")[0], email, password });
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Something went wrong. Please try again.");
    } finally {
      setBusy(false);
    }
  };

  const provider = async (p: string) => {
    setErr("");
    try {
      const sp = (auth as { startProvider?: (n: string) => Promise<unknown> } | undefined)?.startProvider;
      if (sp) await sp(p);
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Could not start that sign-in. Please try again.");
    }
  };

  const inputCls =
    "w-full rounded-2xl border border-[#D6ECE8] bg-white px-4 py-3.5 text-[15px] text-[#0E2B29] outline-none transition placeholder:text-[#9BB8B3] focus:border-[#12A594] focus:ring-4 focus:ring-[#12A594]/15";

  return (
    <div className="relative flex min-h-screen w-full items-center justify-center overflow-hidden px-4 py-10" style={{ fontFamily: FONT, background: "radial-gradient(120% 90% at 50% 0%, #D5F3EE 0%, #EAF9F6 45%, #FFFFFF 100%)" }}>
