        <motion.div
          initial={reduce ? false : { opacity: 0, y: 24 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ type: "spring", stiffness: 100, damping: 18 }}
          className="rounded-[32px] border border-white bg-white/90 p-6 shadow-[0_1px_2px_rgba(14,43,41,0.04),0_30px_70px_-24px_rgba(18,165,148,0.45)] backdrop-blur sm:p-8"
        >
          <div className="mb-6 flex flex-col items-center text-center">
